const invokeUrl = 'https://integrate.api.nvidia.com/v1/chat/completions';
const API_KEY = 'YOUR_API_KEY';

const input = $input.first()?.json?.message?.text;

if (!input) {
  return [
    {
      json: {
        error: true,
        message: 'No Telegram message text found in input.'
      }
    }
  ];
}

const systemPrompt = `You are an expert LinkedIn ghostwriter for tech creators.

Convert a raw idea into a high-quality LinkedIn post.

Rules:
- Start with a very strong hook
- Keep paragraphs short
- Make it clear, sharp, and easy to read
- Sound human, not robotic
- No emojis
- End with exactly 3 relevant hashtags
- Return only the final post text, nothing else`;

const userPrompt = `Turn this idea into a polished LinkedIn post for a tech audience:

"${input}"`;

const payload = {
  model: 'google/gemma-4-31b-it',
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userPrompt }
  ],
  max_tokens: 400,
  temperature: 0.7,
  top_p: 0.9,
  stream: false
};

try {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: invokeUrl,
    headers: {
      Authorization: `Bearer ${API_KEY}`,
      'Content-Type': 'application/json'
    },
    body: payload,
    json: true,
    timeout: 60000
  });

  return [
    {
      json: {
        telegramMessage: response?.choices?.[0]?.message?.content?.trim() || 'Failed to generate post.',
        rawResponse: response
      }
    }
  ];
} catch (error) {
  return [
    {
      json: {
        error: true,
        message: error.message,
        description: error.description,
        statusCode: error.statusCode,
        response: error.response?.body || error.response
      }
    }
  ];
}
